contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // We test that a successful buyShares(to) mints shares to `to` and increases totalSupply accordingly.
    // Parameters:
    // - to: recipient address for minted shares
    // - sendValue: amount of base/quote tokens must already be transferred to the c contract by setup in the environment;
    //   buyShares itself does not take Ether, but the contract may rely on token balances. We accept any inputs.
    function run(address to, uint256 dummy) public payable {
        require(true);

        // Observe totalSupply and recipient balance before the call
        uint256 totalBefore = c.totalSupply();
        uint256 balanceBefore = c.balanceOf(to);

        bool reverted;
        uint256 retShares;
        uint256 retBaseInput;
        uint256 retQuoteInput;

        // Call buyShares. It is external nonReentrant and may revert; capture that.
        try c.buyShares(to) returns (uint256 shares, uint256 baseInput, uint256 quoteInput) {
            reverted = false;
            retShares = shares;
            retBaseInput = baseInput;
            retQuoteInput = quoteInput;
        } catch {
            reverted = true;
        }

        // After-call observations
        uint256 totalAfter = c.totalSupply();
        uint256 balanceAfter = c.balanceOf(to);

        // General rule to assert:
        // If the call did not revert then (1) the recipient's balance increased by exactly shares,
        // and (2) totalSupply increased by exactly shares, and (3) returned shares equals those differences.
        // If the call reverted then no guarantee on these public getters (we simply don't assert anything else).
        assert(
            reverted || (
                balanceAfter >= balanceBefore && totalAfter >= totalBefore &&
                balanceAfter - balanceBefore == retShares &&
                totalAfter - totalBefore == retShares
            )
        );
    }

    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // We observe behavior of buyShares: when it returns (no revert), totalSupply increases exactly by returned shares;
    // the recipient's balance increases by at most that many shares (it cannot mysteriously gain more than minted).
    function run(address to) public payable {
        require(to != address(0));

        // Record pre-call public observations
        uint256 totalBefore = c.totalSupply();
        uint256 balBefore = c.balanceOf(to);

        bool reverted = false;
        uint256 retShares = 0;
        uint256 retBaseInput = 0;
        uint256 retQuoteInput = 0;

        // Top-level external call that may revert
        try c.buyShares(to) returns (uint256 shares, uint256 baseInput, uint256 quoteInput) {
            reverted = false;
            retShares = shares;
            retBaseInput = baseInput;
            retQuoteInput = quoteInput;
        } catch {
            reverted = true;
        }

        // Post-call observations
        uint256 totalAfter = c.totalSupply();
        uint256 balAfter = c.balanceOf(to);

        // Assert a general rule about effects of a successful buyShares:
        // - If it reverted, we make no further guarantees here.
        // - If it succeeded, totalSupply must have increased by exactly the returned shares,
        //   and the recipient's balance must not have increased by more than that amount.
        assert(reverted || (totalAfter >= totalBefore && totalAfter - totalBefore == retShares && balAfter >= balBefore && balAfter - balBefore <= retShares));
    }

    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // Test sellShares: when it returns (no revert), caller's balance decreases exactly by shareAmount
    // and totalSupply decreases exactly by shareAmount. If the call reverts, both observed values remain equal to before.
    function run(uint256 shareAmount, address to, uint256 baseMinAmount, uint256 quoteMinAmount, bytes calldata data, uint256 deadline) public payable {
        require(to != address(0));

        // Observe pre-call public state
        uint256 totalBefore = c.totalSupply();
        uint256 balBefore = c.balanceOf(address(this));

        bool reverted = false;
        uint256 retBaseAmount = 0;
        uint256 retQuoteAmount = 0;

        // Perform the action as a top-level call; capture whether it reverted
        try c.sellShares(shareAmount, to, baseMinAmount, quoteMinAmount, data, deadline) returns (uint256 baseAmount, uint256 quoteAmount) {
            reverted = false;
            retBaseAmount = baseAmount;
            retQuoteAmount = quoteAmount;
        } catch {
            reverted = true;
        }

        // Observe post-call public state
        uint256 totalAfter = c.totalSupply();
        uint256 balAfter = c.balanceOf(address(this));

        // General rule:
        // - If the call reverted, totalSupply and caller balance did not change.
        // - If it succeeded, both totalSupply and caller balance decreased exactly by shareAmount.
        assert(
            (reverted && totalAfter == totalBefore && balAfter == balBefore)
            || (!reverted && totalBefore >= shareAmount && balBefore >= shareAmount && totalBefore - totalAfter == shareAmount && balBefore - balAfter == shareAmount)
        );
    }

    receive() external payable {}
}
